BatchOpDto.declaration:
/// One typed intent inside an account batch, in execution order.
///
/// Serialized with a `kind` tag in SCREAMING_SNAKE_CASE, matching the wire
/// contract of `POST /trade/v1/positions/batch/signed`.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[cfg_attr(feature = "openapi", derive(utoipa::ToSchema))]
#[serde(tag = "kind", rename_all = "SCREAMING_SNAKE_CASE")]
pub enum BatchOpDto {
	/// Split collateral into a complete set: `shares_micro` of each leg.
	Split {
		/// Market row id used for lookup and gating.
		market_id: Uuid,

		/// 0x-prefixed condition id the client signed over; must equal the
		/// stored condition of `market_id`.
		condition_id: String,

		/// Complete-set size in micro units; equals the collateral consumed.
		shares_micro: i64,
	},

	/// Merge a complete set back into collateral.
	Merge {
		/// Market row id used for lookup and gating.
		market_id: Uuid,

		/// 0x-prefixed condition id the client signed over.
		condition_id: String,

		/// Complete-set size in micro units; equals the collateral produced.
		shares_micro: i64,
	},

	/// Redeem the full current balance of a resolved market's positions.
	/// Deliberately sizeless: the chain burns whatever balances exist at
	/// execution, and the engine applies post-confirmation from actuals.
	Redeem {
		/// Market row id used for lookup and gating.
		market_id: Uuid,

		/// 0x-prefixed condition id the client signed over.
		condition_id: String,
	},

	/// Transfer collateral out of the account.
	Withdraw {
		/// 0x-prefixed recipient; never the wallet's own account.
		destination: String,

		/// Amount in micro units.
		amount_micro: i64,
	},

	/// Exact transient approval for a validated Swap API transaction.
	AcrossSwapApprove {
		/// Allowlisted provider target that consumes the allowance.
		spender: String,

		/// Must equal the paired withdrawal input, in micro units.
		amount_micro: i64,
	},

	/// Swap API direct Across route using the universal `deposit` encoding.
	WithdrawAcrossSwapDeposit {
		/// The wallet's own account and Across refund address.
		depositor: String,

		/// Destination recipient.
		recipient: String,

		/// Destination chain id.
		destination_chain_id: u64,

		/// Destination token.
		output_token: String,

		/// Base USDC input and engine debit, in micro units.
		input_amount_micro: i64,

		/// Conservative destination output in token base units.
		output_amount_base_units: u64,

		/// Across quote timestamp.
		quote_timestamp: u32,

		/// Across fill deadline.
		fill_deadline: u32,

		/// Raw offset-or-timestamp exclusivity parameter.
		exclusivity_parameter: u32,

		/// Exclusive relayer or the zero address.
		exclusive_relayer: String,

		/// Public two-byte id, `0x` prefixed.
		integrator_id: Option<String>,
	},

	/// Swap API direct Across route, reconstructed as attributed `depositV3` calldata.
	WithdrawAcrossSwapDepositV3 {
		/// The wallet's own account and Across refund address.
		depositor: String,

		/// Destination recipient.
		recipient: String,

		/// Destination chain id.
		destination_chain_id: u64,

		/// Destination token.
		output_token: String,

		/// Base USDC input and engine debit, in micro units.
		input_amount_micro: i64,

		/// Conservative destination output in token base units.
		output_amount_base_units: u64,

		/// Across quote timestamp.
		quote_timestamp: u32,

		/// Across fill deadline.
		fill_deadline: u32,

		/// Raw offset-or-timestamp exclusivity parameter.
		#[serde(rename = "exclusivity_deadline", alias = "exclusivity_parameter")]
		exclusivity_parameter: u32,

		/// Exclusive relayer or the zero address.
		exclusive_relayer: String,

		/// Public two-byte id, `0x` prefixed.
		integrator_id: Option<String>,
	},

	/// Swap API native-USDC route through Circle CCTP V2.
	WithdrawAcrossSwapCctp {
		/// Destination recipient.
		recipient: String,

		/// Destination chain id pinned to the shared CCTP policy.
		destination_chain_id: u64,

		/// Base USDC input and engine debit, in micro units.
		input_amount_micro: i64,

		/// Maximum destination fee in Base-USDC units.
		max_fee_base_units: u64,

		/// Only address permitted to deliver the Circle message, padded bytes32 hex.
		destination_caller: String,

		/// Exact Circle finality threshold.
		min_finality_threshold: u32,

		/// Public two-byte id, `0x` prefixed.
		integrator_id: Option<String>,
	},
}

